####log2fc
cols <- c("FC")
exp2 <- data[, cols, drop=FALSE]
colnames(exp2) <- "log2foldchange"
exp2_sorted <- exp2 %>% arrange(desc(log2foldchange))
custom_color <- colorRampPalette(c("blue", "white", "red"))(100)
font_size <- 20
paletteLength <- 50
myColor <- colorRampPalette(c("blue", "white", "red"))(paletteLength)
myBreaks <- c(seq(min(exp2_sorted), 0, length.out=ceiling(paletteLength/2) + 1), 
              seq(max(exp2_sorted)/paletteLength, max(exp2_sorted), length.out=floor(paletteLength/2)))

P1=pheatmap(exp2_sorted,
            show_rownames = T,
            show_colnames = T,
            cluster_cols = F,
            cluster_rows=F,
            treeheight_row=50,
            filename='ctrmock_ctrinfected_expression_isoaccpter_log2fc_name.pdf',#输出文件的名称
            fontsize_row=15, #行字体的大小
            fontsize=20,
            height=70,  #输出图片的高度
            width =10,
            # scale = "row",
            angle_col=45, #调整字的角度
            color =myColor,
            breaks = myBreaks,
            cellwidth = 40,
            cellheight = 15,
            border=F,
            # gaps_col = c(2, 3),
            border_color="white"
)


