####zscore 自造
data_zscore <- read.csv("BMDM_CTR_PIC_isoaccepter_zscore.csv", header=T, row.names = 1)
bk <- c(seq(-1,-0.1,by=0.1),seq(0,1,by=0.1))
P2=pheatmap(data_zscore,
            show_rownames = T,
            show_colnames = T,
            cluster_cols = F,
            cluster_rows=F,
            treeheight_row=50,
            filename='zscore name expression.tiff',#输出文件的名称
            fontsize_row=15, #行字体的大小
            fontsize=20,
            height=15,  #输出图片的高度
            width =10,
            # scale = "row",
            angle_col=45, #调整字的角度
